import heapq


def _quota_solver(capacity, tie):
    def solve(data):
        jobs = data["jobs"]
        k = data["k"]
        blocked = set(data.get("blocked", []))
        mandatory = set(data.get("mandatory", []))
        quotas = data.get("quotas", {})
        best_ids = None
        best_value = None
        for subset in combinations(jobs, k):
            ids = {job["id"] for job in subset}
            if not mandatory <= ids or ids & blocked:
                continue
            counts = {}
            for job in subset:
                group = job["group"]
                counts[group] = counts.get(group, 0) + 1
            if any(not low <= counts.get(group, 0) <= high
                   for group, (low, high) in quotas.items()):
                continue
            ends = []
            valid = True
            for job in sorted(subset, key=lambda j: (j["start"], j["end"])):
                while ends and ends[0] <= job["start"]:
                    heapq.heappop(ends)
                heapq.heappush(ends, job["end"])
                if len(ends) > capacity:
                    valid = False
                    break
            if not valid:
                continue
            selected = sorted(ids)
            value = sum(job["value"] for job in subset)
            if (best_ids is None or value > best_value or
                    (value == best_value and
                     (selected > best_ids if tie == "largest" else selected < best_ids))):
                best_ids, best_value = selected, value
        if best_ids is None:
            return {"error": "impossible"}
        return {"selected": best_ids, "value": best_value}
    return solve


def _ledger(data):
    events = data["events"]
    cutoff = data.get("cutoff", 10**9)
    winners = {}
    for pos, event in enumerate(events):
        sequence = event.get("sequence", 0)
        if sequence > cutoff:
            continue
        event_id = event.get("id", "anonymous:" + str(pos))
        key = (sequence, event.get("revision", 0), pos)
        if event_id not in winners or key > winners[event_id][0]:
            winners[event_id] = (key, event)

    balances = dict(data.get("opening", {}))
    mode = data["rounding"]

    def rounded(n, d):
        return (n + d // 2) // d if mode == "half_up" else n // d

    for _, event in winners.values():
        if event.get("void", False):
            continue
        raw = event["price"] * event.get("quantity", 1)
        discount = min(10000, max(0, event.get("discount_bp", 0)))
        net = rounded(raw * (10000 - discount), 10000)
        tax = rounded(raw * event.get("tax_bp", 0), 10000)
        amount = net + tax
        if event.get("kind") == "refund":
            amount = -amount
        key = event.get("account", "default") + "|" + event.get("currency", "USD")
        balances[key] = balances.get(key, 0) + amount
    return {"balances": balances}


def _dependencies(data):
    packages = data["packages"]
    names = sorted(packages, reverse=True)
    features = set(data.get("features", []))
    blocked = data.get("blocked", {})
    pins = data.get("pins", {})
    roots = data["roots"]
    rows = {name: {row["version"]: row for row in versions}
            for name, versions in packages.items()}
    choices = []
    for name in packages:
        allowed = [v for v in rows[name]
                   if v not in blocked.get(name, []) and
                   (name not in pins or v == pins[name])]
        choices.append([None] + allowed)

    best_vector = None
    best_versions = None
    for values in product(*choices):
        selected = {name: version for name, version in zip(packages, values)
                    if version is not None}
        visiting = set()
        visited = set()
        edges = {}
        ok = True

        def visit(name, low, high):
            nonlocal ok
            version = selected.get(name)
            if version is None or not low <= version <= high:
                ok = False
                return
            if name in visiting:
                ok = False
                return
            if name in visited:
                return
            visiting.add(name)
            visited.add(name)
            deps = []
            row = rows[name][version]
            for dep in row.get("deps", []):
                feature = dep.get("feature", "")
                if feature and feature not in features:
                    continue
                deps.append(dep["name"])
                visit(dep["name"], dep["min"], dep["max"])
                if not ok:
                    return
            edges[name] = deps
            visiting.remove(name)

        for name, bounds in roots.items():
            visit(name, bounds[0], bounds[1])
            if not ok:
                break
        if not ok or visited != set(selected):
            continue
        vector = tuple(selected.get(name, -1) for name in names)
        if best_vector is None or vector > best_vector:
            best_vector = vector
            best_versions = selected
    if best_versions is None:
        return {"error": "unsatisfiable"}
    return {"versions": best_versions}


def _routes(data):
    n = data["n"]
    required = data.get("required", [])
    bit_for = {node: 1 << i for i, node in enumerate(required)}
    full = (1 << len(required)) - 1
    start_node = data["source"]
    initial_mask = bit_for.get(start_node, 0)
    coupons = data["coupons"]
    deadline = data["deadline"]
    graph = [[] for _ in range(n)]
    for edge in data["edges"]:
        graph[edge["u"]].append(edge)

    start = data["start"]
    initial = (start_node, initial_mask, 0)
    best = {initial: start}
    queue = [(start, start_node, initial_mask, 0)]
    while queue:
        time, node, mask, used = heapq.heappop(queue)
        state = (node, mask, used)
        if best.get(state) != time:
            continue
        if node == data["target"] and mask == full and used == coupons:
            return {"arrival": time}
        for edge in graph[node]:
            depart = max(time, edge["open"])
            if depart >= edge["close"]:
                continue
            for spend in (0, 1):
                if used + spend > coupons:
                    continue
                duration = edge["duration"]
                if spend:
                    duration = max(1, duration - edge.get("discount", 0))
                arrival = depart + duration
                if arrival > deadline:
                    continue
                nxt = edge["v"]
                next_mask = mask | bit_for.get(nxt, 0)
                next_state = (nxt, next_mask, used + spend)
                if arrival < best.get(next_state, float("inf")):
                    best[next_state] = arrival
                    heapq.heappush(queue, (arrival, nxt, next_mask, used + spend))
    return {"arrival": None}


